// Plain-language mission data editor. Inputs edit the saved lesson, including the answer checks.
function gpEditorRow(row,q){const box=document.createElement('div');box.className='geo-editor';const t=q.geo.task,k=q.geo.kind.slice(3);const answer=row.querySelector('[data-field="answer"]');if(answer)answer.closest('label').hidden=true;
box.innerHTML='<h4>'+esc(GP_TYPES[k])+'</h4><p class="gp-editor-help">Edit the instructions and mission data below. The answer check is calculated from these settings. When changing numbers or locations, update the brief to match.</p><label>Practice source / evidence<textarea data-gp-source rows="3">'+esc(q.geo.source)+'</textarea></label><label>Student mission brief<textarea data-gp-brief rows="3">'+esc(t.brief)+'</textarea></label><label>Review explanation<textarea data-gp-check rows="2">'+esc(t.check)+'</textarea></label><details><summary>Edit locations, cards and model settings</summary><div class="gp-editor-fields"></div></details>';
const host=box.querySelector('.gp-editor-fields'),labels={x:'Column (0=A, 5=F)',y:'Row (0=top, 4=bottom)',w:'Width in squares',h:'Height in squares',bin:'Category number (0=first)',order:'Order position (earliest first)',keep:'Supported by the source',total:'Available tokens',min:'Minimum agreement',max:'Maximum useful allocation',start:'Starting cell / ice mass',goal:'Destination cell',limit:'Maximum route steps',blocked:'Blocked cells',stops:'Required route stops',valid:'Acceptable site cells',cells:'Layer cells',values:'Measurements',zones:'Zone per cell (0, 1 or 2)',samples:'Sample count',rock:'Initial heights',target:'Target / final heights',weather:'Melting in each year',snow:'Snowfall budget',sizes:'Grain sizes',targets:'Targets',solution:'Valid reach energies',questions:'Clue questions',facts:'Candidate facts',memory:'Study then hide the reference',image:'Map image URL',process:'Landscape process',unit:'Graph units',rule:'Site-selection rule',budget:'Token budget',weight:'Equipment weight / limit',label:'Label',needs:'Mission needs',bins:'Category labels'};
function field(parent,key,value,path,owner){const title=labels[key]||key.replace(/^./,c=>c.toUpperCase());if(Array.isArray(value)&&value.every(x=>typeof x==='number'||typeof x==='string')){const label=document.createElement('label');label.textContent=title+(typeof value[0]==='number'?' · comma-separated':' · one per line');const input=document.createElement('textarea');input.rows=Math.min(5,value.length||2);input.value=value.join(typeof value[0]==='number'?', ':'\n');input.oninput=()=>{owner[key]=typeof value[0]==='number'?input.value.split(',').map(x=>Number(x.trim())):input.value.split('\n').filter(x=>x.trim());dirty=true;};label.append(input);parent.append(label);return;}
if(Array.isArray(value)){value.forEach((v,n)=>{const set=document.createElement('fieldset');set.innerHTML='<legend>'+esc(title)+' '+(n+1)+'</legend>';if(Array.isArray(v)){const input=document.createElement('input');input.value=v.join(', ');input.setAttribute('aria-label',title+' '+(n+1));input.oninput=()=>{value[n]=input.value.split(',').map(Number);dirty=true;};set.append(input);}else Object.entries(v).forEach(([a,b])=>field(set,a,b,path+'.'+n+'.'+a,v));parent.append(set);});return;}
if(key==='cover'){const set=document.createElement('fieldset');set.innerHTML='<legend>Needs this project covers</legend>';t.needs.forEach((need,n)=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=!!(value&(1<<n));input.onchange=()=>{owner[key]=input.checked?owner[key]|(1<<n):owner[key]&~(1<<n);dirty=true;};label.append(input,document.createTextNode(need));set.append(label);});parent.append(set);return;}
const label=document.createElement('label');label.textContent=title;const input=document.createElement(typeof value==='string'&&value.length>70?'textarea':'input');input.value=String(value);if(typeof value==='boolean'){input.type='checkbox';input.checked=value;}else if(typeof value==='number'){input.type='number';input.step='1';}input.oninput=()=>{owner[key]=typeof value==='boolean'?input.checked:typeof value==='number'?Number(input.value):input.value;dirty=true;};label.append(input);parent.append(label);}
Object.entries(t).filter(([key])=>!['brief','check','image'].includes(key)).forEach(([key,value])=>field(host,key,value,key,t));
const help=document.createElement('p');help.className='gp-editor-help gp-wide';help.textContent='Grid cell numbers run 0–5 across the top row, 6–11 across the next, ending at 29. Landscape heights use 24 cells in four rows. Route steps and model values must be whole numbers. Save or start checks that the mission can be solved.';host.prepend(help);
row.append(box);box.querySelector('[data-gp-source]').oninput=e=>{q.geo.source=e.target.value;dirty=true;};box.querySelector('[data-gp-brief]').oninput=e=>{t.brief=e.target.value;dirty=true;};box.querySelector('[data-gp-check]').oninput=e=>{t.check=e.target.value;q.answer=e.target.value;dirty=true;};
}
document.addEventListener('DOMContentLoaded',()=>{const previous=window.render_game_to_text;window.render_game_to_text=()=>{const state=JSON.parse(previous());if(game?.session?.geography)state.coordinateSystem='Mission grids: 6 columns A–F left to right, 5 rows 1–5 top to bottom; cell IDs 0–29 in row order. Sculpting: 6 columns by 4 rows. Other models use the units in their brief.';if(game?.session?.geography)state.missions=game.session.lanes.map(l=>({name:l.name,phase:l.phase,kind:game.items[l.index]?.geo.kind,task:game.items[l.index]?.geo.task,state:l.gp}));return JSON.stringify(state);};});
